body:
{
  "head" : {
    "vars" : [ "label", "description", "qid" ]
  },
  "results" : {
    "bindings" : [ {
      "label" : {
        "xml:lang" : "en",
        "type" : "literal",
        "value" : "BlockQuicksort: branch-misprediction-resistant quicksort using block-wise partitioning"
      },
      "description" : {
        "xml:lang" : "en",
        "type" : "literal",
        "value" : "Collects indices of out-of-place elements in blocks to reduce mispredictions and improve cache behavior, accelerating partitioning on modern CPUs."
      },
      "qid" : {
        "type" : "literal",
        "value" : "Q6825358"
      }
    }, {
      "label" : {
        "xml:lang" : "en",
        "type" : "literal",
        "value" : "Bubble sort: adjacent-exchange quadratic comparison sorting algorithm"
      },
      "description" : {
        "xml:lang" : "en",
        "type" : "literal",
        "value" : "Repeatedly swaps adjacent out-of-order pairs, bubbling extremes to the boundary; educational and adaptive but generally inefficient. Variants include cocktail shaker (bidirectional) passes."
      },
      "qid" : {
        "type" : "literal",
        "value" : "Q6825755"
      }
    }, {
      "label" : {
        "xml:lang" : "en",
        "type" : "literal",
        "value" : "Bucket sort: distribution sorting by scattering to buckets then sorting within buckets"
      },
      "description" : {
        "xml:lang" : "en",
        "type" : "literal",
        "value" : "Partitions the value range into buckets whose contents are sorted (often with insertion sort) and concatenated; linear expected time for uniform inputs."
      },
      "qid" : {
        "type" : "literal",
        "value" : "Q6825848"
      }
    }, {
      "label" : {
        "xml:lang" : "en",
        "type" : "literal",
        "value" : "Cocktail shaker sort: bidirectional bubble-sort variant with alternating passes"
      },
      "description" : {
        "xml:lang" : "en",
        "type" : "literal",
        "value" : "Alternates forward and backward adjacent exchanges, moving small and large elements simultaneously toward their places. Slight practical improvement over bubble sort for nearly sorted inputs."
      },
      "qid" : {
        "type" : "literal",
        "value" : "Q6826096"
      }
    }, {
      "label" : {
        "xml:lang" : "en",
        "type" : "literal",
        "value" : "Comb sort: bubble-sort refinement using shrinking gaps (rule-of-1.3) for faster turtle removal"
      },
      "description" : {
        "xml:lang" : "en",
        "type" : "literal",
        "value" : "Uses a gap that shrinks by a factor (≈1.3) each pass, turning into bubble sort when the gap reaches 1; notably reduces small elements 'turtles' near the end. Simple and practical for moderate sizes."
      },
      "qid" : {
        "type" : "literal",
        "value" : "Q6825683"
      }
    }, {
      "label" : {
        "xml:lang" : "en",
        "type" : "literal",
        "value" : "Counting sort: linear-time distribution sorting for small integer ranges"
      },
      "description" : {
        "xml:lang" : "en",
        "type" : "literal",
        "value" : "Counts occurrences of each key value and computes prefix sums to place items into a stable output. Not comparison-based; excels when the key universe is limited relative to n."
      },
      "qid" : {
        "type" : "literal",
        "value" : "Q6825810"
      }
    }, {
      "label" : {
        "xml:lang" : "en",
        "type" : "literal",
        "value" : "Dual-pivot quicksort: two-pivot partitioning with three-way partitions (Java 7 baseline)"
      },
      "description" : {
        "xml:lang" : "en",
        "type" : "literal",
        "value" : "Partitions with two pivots into three regions, improving write locality and branch behavior on practical inputs while preserving n log n average time."
      },
      "qid" : {
        "type" : "literal",
        "value" : "Q6826040"
      }
    }, {
      "label" : {
        "xml:lang" : "en",
        "type" : "literal",
        "value" : "Funnelsort: cache-oblivious sorting using k-funnels and recursive merging"
      },
      "description" : {
        "xml:lang" : "en",
        "type" : "literal",
        "value" : "Uses cache-oblivious k-funnel merge structures to achieve optimal cache complexity without tuning to machine parameters, while maintaining O(n log n) comparisons."
      },
      "qid" : {
        "type" : "literal",
        "value" : "Q6825995"
      }
    }, {
      "label" : {
        "xml:lang" : "en",
        "type" : "literal",
        "value" : "Gnome sort: linear-time-on-near-sorted insertion-like method with single pass pointer"
      },
      "description" : {
        "xml:lang" : "en",
        "type" : "literal",
        "value" : "Walks the array and swaps backwards when an inversion is found, resuming forward scanning; same worst-case as insertion sort but without nested loops. Mostly of pedagogical interest."
      },
      "qid" : {
        "type" : "literal",
        "value" : "Q6825420"
      }
    }, {
      "label" : {
        "xml:lang" : "en",
        "type" : "literal",
        "value" : "Heapsort: selection-by-heap comparison sorting algorithm with in-place O(n log n) worst-case"
      },
      "description" : {
        "xml:lang" : "en",
        "type" : "literal",
        "value" : "Builds a heap then repeatedly extracts the extremum and restores the heap. Guarantees O(n log n) time and O(1) auxiliary space, at the cost of more data movement than quicksort."
      },
      "qid" : {
        "type" : "literal",
        "value" : "Q6825950"
      }
    }, {
      "label" : {
        "xml:lang" : "en",
        "type" : "literal",
        "value" : "Insertion sort: simple incremental comparison sorting by local insertion"
      },
      "description" : {
        "xml:lang" : "en",
        "type" : "literal",
        "value" : "Maintains a growing sorted prefix, inserting each new element by shifting larger items; runs in O(n^2) time but is fast on tiny or nearly-sorted inputs and valuable inside hybrids."
      },
      "qid" : {
        "type" : "literal",
        "value" : "Q6825598"
      }
    }, {
      "label" : {
        "xml:lang" : "en",
        "type" : "literal",
        "value" : "Introsort: introspective hybrid of quicksort, heapsort fallback, and insertion sort base cases"
      },
      "description" : {
        "xml:lang" : "en",
        "type" : "literal",
        "value" : "Begins with quicksort but monitors recursion depth and switches to heapsort to guarantee O(n log n) worst-case; typically uses insertion sort for tiny partitions. Forms the basis of many std::sort implementations."
      },
      "qid" : {
        "type" : "literal",
        "value" : "Q6825666"
      }
    }, {
      "label" : {
        "xml:lang" : "en",
        "type" : "literal",
        "value" : "Mergesort: stable divide-and-conquer sorting via recursive splitting and sequential merging"
      },
      "description" : {
        "xml:lang" : "en",
        "type" : "literal",
        "value" : "Recursively splits the sequence and merges sorted halves; stable with O(n log n) comparisons and O(n) extra space. Suitable for external sorting and as a stable core of hybrids such as timsort."
      },
      "qid" : {
        "type" : "literal",
        "value" : "Q6825472"
      }
    }, {
      "label" : {
        "xml:lang" : "en",
        "type" : "literal",
        "value" : "Quicksort: in-place partition-based divide-and-conquer comparison sorting algorithm (Hoare partition scheme)"
      },
      "description" : {
        "xml:lang" : "en",
        "type" : "literal",
        "value" : "Recursively partitions the array around a pivot and sorts subarrays in place; average-case O(n log n) with small constant factors. Performance hinges on pivot selection and handling of equal keys; randomized and three-way variants mitigate worst cases."
      },
      "qid" : {
        "type" : "literal",
        "value" : "Q6825489"
      }
    }, {
      "label" : {
        "xml:lang" : "en",
        "type" : "literal",
        "value" : "Radix sort: LSD/MSD multi-pass distribution sorting by digits or characters"
      },
      "description" : {
        "xml:lang" : "en",
        "type" : "literal",
        "value" : "Processes keys by radix digits using stable bucketing (LSD) or recursive partitioning (MSD); achieves O((w/b)·n) time for w-bit keys. Widely used for integers and strings and as a GPU workhorse."
      },
      "qid" : {
        "type" : "literal",
        "value" : "Q6825804"
      }
    }, {
      "label" : {
        "xml:lang" : "en",
        "type" : "literal",
        "value" : "Selection sort: quadratic-time comparison sorting by repeated minimum selection"
      },
      "description" : {
        "xml:lang" : "en",
        "type" : "literal",
        "value" : "Finds the next smallest item (e.g., by linear scan) and places it in order; performs O(n^2) comparisons but only O(n) moves. Useful for tiny arrays or when writes are costly."
      },
      "qid" : {
        "type" : "literal",
        "value" : "Q6825795"
      }
    }, {
      "label" : {
        "xml:lang" : "en",
        "type" : "literal",
        "value" : "Shellsort: gapped-insertion comparison sorting with diminishing increment sequences"
      },
      "description" : {
        "xml:lang" : "en",
        "type" : "literal",
        "value" : "Sorts elements far apart before reducing the gap to 1, greatly reducing inversions; performance depends on the increment sequence. Useful for medium sizes and partially ordered data."
      },
      "qid" : {
        "type" : "literal",
        "value" : "Q6825823"
      }
    }, {
      "label" : {
        "xml:lang" : "en",
        "type" : "literal",
        "value" : "Smoothsort: heapsort variant adaptive to presortedness using Leonardo heaps"
      },
      "description" : {
        "xml:lang" : "en",
        "type" : "literal",
        "value" : "Achieves O(n log n) worst-case but approaches O(n) on partially sorted inputs by structuring a forest of heap-ordered Leonardo trees. Complex but in-place and comparison-based."
      },
      "qid" : {
        "type" : "literal",
        "value" : "Q6825725"
      }
    }, {
      "label" : {
        "xml:lang" : "en",
        "type" : "literal",
        "value" : "Timsort: stable hybrid mergesort that exploits natural runs with galloping merges (Python/Java standard)"
      },
      "description" : {
        "xml:lang" : "en",
        "type" : "literal",
        "value" : "Detects monotone runs and merges them with adaptive strategies, providing excellent real-world performance while retaining O(n log n) bound. Designed for partially ordered data and stability-sensitive applications."
      },
      "qid" : {
        "type" : "literal",
        "value" : "Q6825797"
      }
    }, {
      "label" : {
        "xml:lang" : "en",
        "type" : "literal",
        "value" : "Tournament sort: selection via tournament tree (winner tree) for O(n log n) sorting"
      },
      "description" : {
        "xml:lang" : "en",
        "type" : "literal",
        "value" : "Builds a tree of pairwise winners to repeatedly select the next element, updating along the root path; directly connected to external run generation and replacement selection."
      },
      "qid" : {
        "type" : "literal",
        "value" : "Q6825991"
      }
    }, {
      "label" : {
        "xml:lang" : "en",
        "type" : "literal",
        "value" : "Weak-heapsort: heap-based sorting using weak-heap structure with near-optimal comparisons"
      },
      "description" : {
        "xml:lang" : "en",
        "type" : "literal",
        "value" : "Uses a weak-heap priority queue to reduce comparisons and branch mispredictions relative to classic heapsort. Implements in-place sorting with favorable constants in practice."
      },
      "qid" : {
        "type" : "literal",
        "value" : "Q6825366"
      }
    } ]
  }
}

request.data:
SELECT DISTINCT ?label ?description ?qid
WHERE {
  ?algo wdt:P31 wd:Q127020 ;
        rdfs:label ?label .
  FILTER(LANG(?label) = "en")
  # algorithmic task: Sorting items under a total order
  wd:Q6825656 wdt:P1578 ?algo .
  OPTIONAL { ?algo schema:description ?description . FILTER(LANG(?description) = "en") }
  BIND(STRAFTER(STR(?algo), STR(wd:)) AS ?qid)
}
ORDER BY LCASE(?label)
LIMIT 101
